{
  "analysis": "QEMU 8.2.2 is installed with both i386 and x86_64 binaries. The disk image is a 256MB raw image. noVNC and websockify are already installed. nginx is installed but not yet running. Ports 80 and 5901 are free. We now need to launch QEMU with snapshot mode, VNC :1, and monitor socket, then configure websockify and nginx for the web interface.",
  "plan": "Start QEMU as a daemon with snapshot mode, VNC on 0.0.0.0:1 (port 5901), and a Unix monitor socket at /tmp/qemu-monitor.sock. Then start websockify to proxy WebSocket connections to the VNC server. Configure nginx to serve noVNC on port 80 and proxy /websockify to websockify. Finally verify all processes and ports are working, and test the monitor socket.",
  "commands": [
    {
      "keystrokes": "rm -f /tmp/qemu-monitor.sock /tmp/qemu.pid
qemu-system-i386 \
  -drive file=/app/isos/win311.img,format=raw,snapshot=on \
  -m 256 \
  -vnc 0.0.0.0:1 \
  -chardev socket,id=mon0,path=/tmp/qemu-monitor.sock,server=on,wait=off \
  -mon chardev=mon0,mode=readline \
  -daemonize \
  -pidfile /tmp/qemu.pid
echo "QEMU exit code: $?"
",
      "duration": 2.0
    },
    {
      "keystrokes": "nohup websockify 0.0.0.0:6080 localhost:5901 > /tmp/websockify.log 2>&1 &
",
      "duration": 0.5
    },
    {
      "keystrokes": "rm -f /etc/nginx/sites-enabled/default
cat > /etc/nginx/sites-available/novnc << 'NGINX'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    root /usr/share/novnc;
    index index.html;

    location /websockify {
        proxy_pass http://127.0.0.1:6080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 3600;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
NGINX
ln -sf /etc/nginx/sites-available/novnc /etc/nginx/sites-enabled/novnc
cat > /usr/share/novnc/index.html << 'HTML'
<!DOCTYPE html>
<html>
<head>
<meta http-equiv="refresh" content="0; url=vnc.html?autoconnect=true&path=websockify">
</head>
<body>Redirecting to noVNC...</body>
</html>
HTML
nginx -t && nginx
",
      "duration": 1.0
    },
    {
      "keystrokes": "sleep 2
echo "=== QEMU Process ==="
ps aux | grep qemu-system | grep -v grep
echo "=== Ports ==="
ss -ltnp | grep -E ':5901|:6080|:80 '
echo "=== Monitor Socket ==="
ls -la /tmp/qemu-monitor.sock
echo "=== Monitor Test ==="
python3 -c "
import socket, time
s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
s.connect('/tmp/qemu-monitor.sock')
s.send(b'info status
')
time.sleep(0.5)
print(s.recv(4096).decode())
s.close()
"
",
      "duration": 3.0
    }
  ]
}
